<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Services\Audit\AuditLogger; use App\Services\SettingsService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\View\View;
class SettingsController extends Controller {
 public function edit(SettingsService $s): View { return view('admin.settings.edit',['values'=>[ 'ai.enabled'=>$s->bool('ai.enabled'), 'ai.min_quality_score'=>$s->float('ai.min_quality_score',.80), 'ai.min_critical_confidence'=>$s->float('ai.min_critical_confidence',.85), 'check_et.enabled'=>$s->bool('check_et.enabled'), 'check_et.outage_mode'=>$s->get('check_et.outage_mode','review'), 'check_et.failure_mode'=>$s->get('check_et.failure_mode','review'), 'validation.warning_minutes'=>$s->int('validation.warning_minutes',60), 'validation.serious_minutes'=>$s->int('validation.serious_minutes',180), 'validation.alarming_minutes'=>$s->int('validation.alarming_minutes',360), 'validation.critical_minutes'=>$s->int('validation.critical_minutes',720), 'validation.receiver_name_similarity'=>$s->float('validation.receiver_name_similarity',.90), 'validation.require_receiver_name'=>$s->bool('validation.require_receiver_name',true), ]]); }
 public function update(Request $request, SettingsService $s, AuditLogger $audit): RedirectResponse { $d=$request->validate(['ai_min_quality'=>['required','numeric','between:0.5,1'],'ai_min_confidence'=>['required','numeric','between:0.5,1'],'warning_minutes'=>['required','integer','min:1'],'serious_minutes'=>['required','integer','gt:warning_minutes'],'alarming_minutes'=>['required','integer','gt:serious_minutes'],'critical_minutes'=>['required','integer','gt:alarming_minutes'],'receiver_similarity'=>['required','numeric','between:0.5,1'],'check_et_outage_mode'=>['required','in:review,allow'],'check_et_failure_mode'=>['required','in:review,allow']]); $pairs=['ai.enabled'=>$request->boolean('ai_enabled'),'ai.min_quality_score'=>(float)$d['ai_min_quality'],'ai.min_critical_confidence'=>(float)$d['ai_min_confidence'],'check_et.enabled'=>$request->boolean('check_et_enabled'),'check_et.outage_mode'=>$d['check_et_outage_mode'],'check_et.failure_mode'=>$d['check_et_failure_mode'],'validation.warning_minutes'=>(int)$d['warning_minutes'],'validation.serious_minutes'=>(int)$d['serious_minutes'],'validation.alarming_minutes'=>(int)$d['alarming_minutes'],'validation.critical_minutes'=>(int)$d['critical_minutes'],'validation.receiver_name_similarity'=>(float)$d['receiver_similarity'],'validation.require_receiver_name'=>$request->boolean('require_receiver_name')]; foreach($pairs as $k=>$v)$s->set($k,$v,str($k)->before('.')->toString()); $audit->log('settings.updated',null,null,$pairs); return back()->with('success','Platform settings updated.'); }
}
